/**
 * Shell Component
 *
 * Main shell layout using SidebarProvider from @ensemble-edge/ui.
 * Provides responsive sidebar with collapsible states.
 */

import * as React from 'react';
import { useEffect } from 'react';
import { useSignals } from '@preact/signals-react/runtime';

import {
  SidebarProvider,
  SidebarInset,
  SidebarTrigger,
  Separator,
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbList,
  BreadcrumbPage,
  Toaster,
} from '@ensemble-edge/ui';

import { AppSidebar } from './AppSidebar';
import { Viewport } from './Viewport';
import {
  fetchWorkspace,
  fetchUser,
  fetchTheme,
  fetchNav,
  currentPath,
} from '../state';

// Map paths to breadcrumb labels
const pathLabels: Record<string, string> = {
  '/': 'Home',
  '/brand': 'Brand',
  '/people': 'People',
  '/settings': 'Settings',
  '/apps': 'Apps',
  '/auth': 'Auth & Security',
  '/audit': 'Audit Log',
  '/nav': 'Navigation',
  '/knowledge': 'Knowledge',
};

export function Shell() {
  useSignals();

  const path = currentPath.value;

  // Initialize on mount
  useEffect(() => {
    // Fetch all data in parallel
    Promise.all([
      fetchWorkspace(),
      fetchUser(),
      fetchTheme(),
      fetchNav(),
    ]).catch((err) => {
      console.error('[Shell] Failed to initialize:', err);
    });
  }, []);

  // Get breadcrumb label
  const pageLabel = pathLabels[path] || path.split('/').pop() || 'Page';

  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset className="h-svh overflow-hidden">
        {/* Header with breadcrumb */}
        <header className="flex h-16 shrink-0 items-center gap-2 border-b px-4">
          <SidebarTrigger className="-ml-1" />
          <Separator orientation="vertical" className="mr-2 h-4" />
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem>
                <BreadcrumbPage>{pageLabel}</BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>
        </header>

        {/* Main content — scrollable.
            `flex flex-col` is load-bearing: it establishes the flex context
            so child `flex-1` (e.g. AppViewPage's iframe wrapper) actually
            grows. Without it, iframes collapse to their intrinsic ~150px
            and look broken even though the iframe content is rendering
            correctly. Diagnosed in v0.1.6 by curalisto's agent in a
            deployed v0.1.5 environment. */}
        <div className="flex-1 overflow-y-auto flex flex-col" style={{ padding: 'var(--content-padding, 1.5rem)' }}>
          <Viewport />
        </div>
      </SidebarInset>

      {/* Toast notifications (alert-styled) */}
      <Toaster position="bottom-right" />
    </SidebarProvider>
  );
}
